    const ok = [], bad = [];
    nums.forEach((n) => { const r = ruleLine(n); if (r) ok.push(`<details><summary>✓ ${esc(n)} — ${esc(r.head)}</summary><div style="opacity:.85">${esc(r.line)}</div></details>`); else if (/rule/i.test(txt)) bad.push(n); });
